                          <span>{s.area || "—"}</span>
                          <span className="cell-category-inline">{formatDateTime(s.created_at)}</span>
                        </div>
                      </td>
                      <td>
                        <div className="cell-product">
                          <strong title={s.product_name}>{s.product_name}</strong>
